import{_ as t,o as d,c as o,ag as a}from"./chunks/framework.8tqBsFWt.js";const _=JSON.parse('{"title":"Compensation Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools/compensation.md","filePath":"reference/tools/compensation.md"}'),r={name:"reference/tools/compensation.md"};function s(i,e,n,l,c,p){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="compensation-tools" tabindex="-1">Compensation Tools <a class="header-anchor" href="#compensation-tools" aria-label="Permalink to &quot;Compensation Tools&quot;">​</a></h1><p>Per-discipline, per-level salary bands, so an owner can see whether a person is paid correctly for their level — plus the employer cost multiplier that separates gross pay from what the agency actually spends on someone, and the ability to seed a discipline&#39;s bands from published government wage data for the agency&#39;s own region.</p><p>Pay itself is always derived from the cost rate already recorded for each person — these tools only read and band it; they never enter a salary figure separately.</p><p>All compensation tools are <strong>Owner/Admin only</strong> and <strong>console-only</strong> — not reachable from Slack; use the web console.</p><hr><h2 id="list_discipline_level_bands" tabindex="-1">list_discipline_level_bands <a class="header-anchor" href="#list_discipline_level_bands" aria-label="Permalink to &quot;list_discipline_level_bands {#list_discipline_level_bands}&quot;">​</a></h2><p>List every discipline&#39;s salary bands across all four levels.</p><p><strong>Reads from</strong>: discipline compensation bands</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code></p><p><strong>Returns</strong>: one row per <code>(discipline, level)</code> pair that has a band set — <code>discipline_id</code>, <code>level</code> (1–4), <code>salary_min</code>, <code>salary_max</code>.</p><hr><h2 id="set_discipline_level_band" tabindex="-1">set_discipline_level_band <a class="header-anchor" href="#set_discipline_level_band" aria-label="Permalink to &quot;set_discipline_level_band {#set_discipline_level_band}&quot;">​</a></h2><p>Set the salary band for one discipline at one level.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Writes to</strong>: discipline compensation bands</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>discipline_id</code></td><td>✅</td><td>Must be an active discipline</td></tr><tr><td><code>level</code></td><td>✅</td><td>Integer, <code>1</code>–<code>4</code></td></tr><tr><td><code>salary_min</code></td><td></td><td>Non-negative</td></tr><tr><td><code>salary_max</code></td><td></td><td>Non-negative, must be ≥ <code>salary_min</code> when both are set</td></tr></tbody></table><p>Leaving <code>salary_min</code>/<code>salary_max</code> empty clears that band&#39;s edge.</p><p>A discipline&#39;s four levels are contiguous by design — see <code>set_discipline_ladder</code> for setting all four at once as a single connected ladder rather than one band at a time.</p><hr><h2 id="set_discipline_ladder" tabindex="-1">set_discipline_ladder <a class="header-anchor" href="#set_discipline_ladder" aria-label="Permalink to &quot;set_discipline_ladder {#set_discipline_ladder}&quot;">​</a></h2><p>Set a discipline&#39;s entire 1–4 salary ladder in one call, as five connected boundaries rather than four independent bands.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Writes to</strong>: discipline compensation bands (all four levels, in one transaction)</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>discipline_id</code></td><td>✅</td><td>Must be an active discipline</td></tr><tr><td><code>floor</code></td><td></td><td>Level 1&#39;s minimum</td></tr><tr><td><code>boundary_12</code></td><td></td><td>Level 1&#39;s maximum / Level 2&#39;s minimum</td></tr><tr><td><code>boundary_23</code></td><td></td><td>Level 2&#39;s maximum / Level 3&#39;s minimum</td></tr><tr><td><code>boundary_34</code></td><td></td><td>Level 3&#39;s maximum / Level 4&#39;s minimum</td></tr><tr><td><code>ceiling</code></td><td></td><td>Level 4&#39;s maximum</td></tr></tbody></table><p>The five boundaries must be <strong>strictly ascending</strong> (<code>floor &lt; boundary_12 &lt; boundary_23 &lt; boundary_34 &lt; ceiling</code>), or <strong>all five must be left empty</strong> to clear the ladder entirely. Any other mix — a partial set, or boundaries out of order — is rejected and nothing is written.</p><p>On success, four bands are written that share their adjacent endpoints exactly: Level 1 is <code>floor</code>–<code>boundary_12</code>, Level 2 is <code>boundary_12</code>–<code>boundary_23</code>, and so on through Level 4 at <code>boundary_34</code>–<code>ceiling</code>.</p><hr><h2 id="set_employer_cost_multiplier" tabindex="-1">set_employer_cost_multiplier <a class="header-anchor" href="#set_employer_cost_multiplier" aria-label="Permalink to &quot;set_employer_cost_multiplier {#set_employer_cost_multiplier}&quot;">​</a></h2><p>Set the tenant&#39;s employer cost multiplier — for every $1 of gross pay, what the agency actually spends once employer payroll taxes, benefits, and retirement match are added.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Updates</strong>: tenant config</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>employer_cost_multiplier</code></td><td>✅</td><td>Number, <code>1.0</code>–<code>2.0</code>. <code>1.0</code> means recorded cost rates are already gross-pay-only.</td></tr></tbody></table><p>The multiplier covers only costs that scale with a person&#39;s pay — it deliberately excludes flat operating costs (software, equipment, office, recruiting) even when those happen to be billed per person.</p><hr><h2 id="preview_discipline_ladders" tabindex="-1">preview_discipline_ladders <a class="header-anchor" href="#preview_discipline_ladders" aria-label="Permalink to &quot;preview_discipline_ladders {#preview_discipline_ladders}&quot;">​</a></h2><p>Fetch a proposed salary ladder for every mapped discipline from published wage data, for review before applying. <strong>Read-only — fetching never writes anything.</strong></p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>location</code></td><td></td><td><code>&quot;City, ST&quot;</code>. Falls back to the tenant&#39;s configured HQ location; fails if neither is set.</td></tr></tbody></table><p><strong>Returns</strong>: <code>location</code>, and <code>proposals</code> — one result per active discipline. A discipline with no occupation mapped is returned as <code>unmapped</code> without ever being queried. A mapped discipline&#39;s result carries a <code>status</code> of <code>ok</code> (with the geographic tier used, the wage anchors, and the resulting ladder), <code>unavailable</code> (no usable data at any geographic tier), <code>data-error</code> (the published data didn&#39;t produce a sane ladder), or <code>failed</code> (the lookup itself failed).</p><p>Applying a proposed ladder is a separate, explicit step through <code>set_discipline_ladder</code> — nothing here is applied automatically.</p><hr><h2 id="set_discipline_soc_code" tabindex="-1">set_discipline_soc_code <a class="header-anchor" href="#set_discipline_soc_code" aria-label="Permalink to &quot;set_discipline_soc_code {#set_discipline_soc_code}&quot;">​</a></h2><p>Map a discipline to a real government occupation code, so its bands can eventually be seeded from published regional wage data.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Updates</strong>: <code>08. Disciplines</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>discipline_id</code></td><td>✅</td><td>Must be an active discipline</td></tr><tr><td><code>soc_code</code></td><td></td><td>Must be a recognized occupation code from the committed occupation taxonomy. Empty clears the mapping.</td></tr></tbody></table><p>There is no fuzzy matching — a code that isn&#39;t in the recognized taxonomy is rejected, since a wrong match would produce a confident, wrong salary figure. The occupation is always picked explicitly from a grouped list.</p>',52)])])}const u=t(r,[["render",s]]);export{_ as __pageData,u as default};
